"use client";
/**
 * Clio mini calendar: a month as a labelled grid, today in the accent and a dot under the days you marked. Arrow keys
 * move between days; Enter or Space picks one. Dates are worked out in UTC, so the grid is the same in every time zone.
 */
import { type KeyboardEvent, type ReactNode, useId, useMemo, useRef, useState } from "react";
import { ClioTile, type ClioTileProps, clioTileAliveDelay, useClioAlive } from "./theme";

const CSS = `
.clio-cal__grid{width:100%;margin-top:8px;border-collapse:collapse;table-layout:fixed;font-variant-numeric:tabular-nums}
.clio-cal__grid th{padding:0 0 3px;font-family:var(--clio-mono);font-size:9.5px;font-weight:400;line-height:1.2;color:var(--clio-ink-tertiary);text-align:center;transition:color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-cal__grid td{padding:0;text-align:center}
.clio-cal__day{position:relative;display:grid;place-items:center;height:var(--clio-cal-row,21px);margin:0 auto;aspect-ratio:1;max-width:100%;border-radius:999px;font-size:11px;line-height:1;color:var(--clio-ink);cursor:default;transition:background-color 220ms ease,color var(--clio-mode-ms) var(--clio-mode-ease)}
td[data-outside] .clio-cal__day{color:var(--clio-ink-tertiary)}
td[data-selectable] .clio-cal__day{cursor:pointer}
td[data-selectable]:hover .clio-cal__day{background:var(--clio-track)}
td:focus{outline:none}
td:focus-visible .clio-cal__day{outline:2px solid var(--clio-accent);outline-offset:1px}
td[aria-selected="true"] .clio-cal__day{background:var(--clio-ink);color:var(--clio-tile)}
.clio-cal__today{position:absolute;inset:0;border-radius:999px;background:var(--clio-accent);transform:scale(.4);opacity:0;transition:transform 520ms var(--clio-alive-ease),opacity 300ms ease,background-color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-cal[data-alive] .clio-cal__today{transform:none;opacity:1;transition-delay:var(--clio-cal-today-delay,0ms)}
td[data-today] .clio-cal__num{position:relative;color:var(--clio-on-accent);font-weight:500}
.clio-cal__dot{position:absolute;left:50%;bottom:1px;width:3px;height:3px;margin-left:-1.5px;border-radius:999px;background:var(--clio-bar);transform:scale(0);transition:transform 360ms var(--clio-alive-ease),background-color var(--clio-mode-ms) var(--clio-mode-ease);transition-delay:var(--clio-dot-delay,0ms),0ms}
.clio-cal[data-alive] .clio-cal__dot{transform:none}
td[data-today] .clio-cal__dot{background:var(--clio-on-accent);bottom:2px}
@media (prefers-reduced-motion:reduce){.clio-cal__today,.clio-cal__dot{transition:background-color 200ms linear}}
`;

export interface ClioCalendarDay {
  /** "YYYY-MM-DD". */
  iso: string;
  year: number;
  /** 1–12. */
  month: number;
  day: number;
  /** 0 is Sunday. */
  weekday: number;
  /** In the month shown, not a leading or trailing day. */
  inMonth: boolean;
  isToday: boolean;
}

export interface ClioMonthGridOptions {
  /** 0 starts weeks on Sunday, 1 on Monday. */
  weekStartsOn?: number;
  /** Today as "YYYY-MM-DD". */
  today?: string | null;
  /** Always six weeks, so the grid keeps its height from month to month. */
  fixedWeeks?: boolean;
}

const DAY_MS = 86_400_000;
const pad = (n: number) => String(n).padStart(2, "0");

/**
 * The weeks of a month (1–12) with the days before and after it that complete them. Worked out in UTC, so it is the
 * same in every time zone.
 */
export function clioMonthGrid(
  year: number,
  month: number,
  { weekStartsOn = 1, today = null, fixedWeeks = false }: ClioMonthGridOptions = {},
): ClioCalendarDay[][] {
  if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12)
    throw new RangeError(`No such month: ${year}-${month}`);
  const start = ((Math.round(weekStartsOn) % 7) + 7) % 7;
  const first = Date.UTC(year, month - 1, 1);
  const lead = (new Date(first).getUTCDay() - start + 7) % 7;
  const length = new Date(Date.UTC(year, month, 0)).getUTCDate();
  const cells = fixedWeeks ? 42 : Math.ceil((lead + length) / 7) * 7;
  const weeks: ClioCalendarDay[][] = [];
  for (let i = 0; i < cells; i++) {
    const date = new Date(first + (i - lead) * DAY_MS);
    const day: ClioCalendarDay = {
      iso: `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`,
      year: date.getUTCFullYear(),
      month: date.getUTCMonth() + 1,
      day: date.getUTCDate(),
      weekday: date.getUTCDay(),
      inMonth: date.getUTCMonth() === month - 1,
      isToday: false,
    };
    day.isToday = day.iso === today;
    if (i % 7 === 0) weeks.push([]);
    weeks[weeks.length - 1]?.push(day);
  }
  return weeks;
}

/** A moment as "YYYY-MM-DD" in a time zone (the reader's own by default). */
export function clioIsoDate(date: Date | number, timeZone?: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    ...(timeZone ? { timeZone } : {}),
  }).formatToParts(date);
  const part = (type: string) => parts.find((p) => p.type === type)?.value ?? "";
  return `${part("year")}-${part("month")}-${part("day")}`;
}

export interface ClioCalendarProps extends Omit<ClioTileProps, "children" | "label" | "onSelect"> {
  year: number;
  /** 1–12. */
  month: number;
  /** The caption; the month's name by default. */
  label?: ReactNode;
  /** Today as "YYYY-MM-DD". */
  today?: string | null;
  /** Days with a dot, as "YYYY-MM-DD". */
  marked?: readonly string[];
  /** What a dot means, read out with the day. */
  markedLabel?: string;
  weekStartsOn?: number;
  fixedWeeks?: boolean;
  /** The picked day (controlled), "YYYY-MM-DD". */
  selected?: string | null;
  defaultSelected?: string | null;
  /** Makes days pickable. */
  onSelect?: (iso: string) => void;
  locale?: string;
  /** Pop the dots and today in after the rise. */
  animate?: boolean;
}

export function ClioCalendar({
  year,
  month,
  label,
  today = null,
  marked = [],
  markedLabel = "marked",
  weekStartsOn = 1,
  fixedWeeks = false,
  selected,
  defaultSelected = null,
  onSelect,
  locale = "en-GB",
  animate = true,
  riseIndex,
  riseDelay,
  className,
  ...tile
}: ClioCalendarProps) {
  const weeks = useMemo(
    () => clioMonthGrid(year, month, { weekStartsOn, today, fixedWeeks }),
    [year, month, weekStartsOn, today, fixedWeeks],
  );
  const days = weeks.flat();
  const marks = useMemo(() => new Set(marked), [marked]);
  const [own, setOwn] = useState(defaultSelected);
  const picked = selected === undefined ? own : selected;
  const firstFocus =
    days.find((d) => d.iso === picked) ??
    days.find((d) => d.isToday) ??
    days.find((d) => d.inMonth) ??
    days[0];
  const [focus, setFocus] = useState(firstFocus?.iso ?? "");
  const focusIso = days.some((d) => d.iso === focus) ? focus : (firstFocus?.iso ?? "");
  const cells = useRef(new Map<string, HTMLTableCellElement>());
  const alive = useClioAlive(clioTileAliveDelay(riseIndex, riseDelay), animate);
  const gridId = useId();
  const monthName = new Intl.DateTimeFormat(locale, { month: "long", timeZone: "UTC" }).format(
    Date.UTC(year, month - 1, 1),
  );
  const monthYear = new Intl.DateTimeFormat(locale, {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(Date.UTC(year, month - 1, 1));
  const weekdays = Array.from({ length: 7 }, (_, i) => {
    const date = Date.UTC(2024, 0, 7 + ((weekStartsOn + i) % 7)); // 7 January 2024 was a Sunday.
    return {
      short: new Intl.DateTimeFormat(locale, { weekday: "narrow", timeZone: "UTC" }).format(date),
      long: new Intl.DateTimeFormat(locale, { weekday: "long", timeZone: "UTC" }).format(date),
    };
  });
  const spoken = (d: ClioCalendarDay) =>
    [
      new Intl.DateTimeFormat(locale, {
        weekday: "long",
        day: "numeric",
        month: "long",
        timeZone: "UTC",
      }).format(Date.UTC(d.year, d.month - 1, d.day)),
      d.isToday ? "today" : null,
      marks.has(d.iso) ? markedLabel : null,
    ]
      .filter(Boolean)
      .join(", ");
  const choose = (iso: string) => {
    if (!onSelect) return;
    if (selected === undefined) setOwn(iso);
    onSelect(iso);
  };
  const onKey = (event: KeyboardEvent<HTMLTableCellElement>, index: number) => {
    const moves: Record<string, number> = {
      ArrowLeft: -1,
      ArrowRight: 1,
      ArrowUp: -7,
      ArrowDown: 7,
    };
    let to: number | null = event.key in moves ? index + (moves[event.key] ?? 0) : null;
    if (event.key === "Home") to = index - (index % 7);
    if (event.key === "End") to = index - (index % 7) + 6;
    if ((event.key === "Enter" || event.key === " ") && days[index]) {
      event.preventDefault();
      choose(days[index].iso);
      return;
    }
    if (to === null) return;
    event.preventDefault();
    const target = days[Math.min(days.length - 1, Math.max(0, to))];
    if (!target) return;
    setFocus(target.iso);
    cells.current.get(target.iso)?.focus();
  };
  const markedOrder = days.filter((d) => marks.has(d.iso)).map((d) => d.iso);

  return (
    <ClioTile
      {...tile}
      label={label ?? monthName}
      riseIndex={riseIndex}
      riseDelay={riseDelay}
      className={className ? `clio-cal ${className}` : "clio-cal"}
      data-alive={alive ? "" : undefined}
    >
      <style>{CSS}</style>
      <table
        className="clio-cal__grid"
        // biome-ignore lint/a11y/noNoninteractiveElementToInteractiveRole: the APG date grid is a table with role="grid"
        role="grid"
        aria-label={monthYear}
        id={gridId}
      >
        <thead>
          <tr>
            {weekdays.map((w) => (
              <th key={w.long} scope="col" abbr={w.long}>
                {w.short}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {weeks.map((week) => (
            <tr key={week[0]?.iso}>
              {week.map((d) => {
                const index = days.indexOf(d);
                const dot = markedOrder.indexOf(d.iso);
                return (
                  <td
                    key={d.iso}
                    ref={(node) => {
                      if (node) cells.current.set(d.iso, node);
                      else cells.current.delete(d.iso);
                    }}
                    // biome-ignore lint/a11y/noNoninteractiveElementToInteractiveRole: each day is a gridcell of the APG date grid
                    role="gridcell"
                    tabIndex={d.iso === focusIso ? 0 : -1}
                    aria-label={spoken(d)}
                    aria-selected={onSelect ? d.iso === picked : undefined}
                    aria-current={d.isToday ? "date" : undefined}
                    data-outside={d.inMonth ? undefined : ""}
                    data-today={d.isToday ? "" : undefined}
                    data-selectable={onSelect ? "" : undefined}
                    onKeyDown={(event) => onKey(event, index)}
                    onFocus={() => setFocus(d.iso)}
                    onClick={() => choose(d.iso)}
                  >
                    <span className="clio-cal__day" aria-hidden="true">
                      {d.isToday ? (
                        <span
                          className="clio-cal__today"
                          style={{
                            ["--clio-cal-today-delay" as string]: `${markedOrder.length * 24 + 120}ms`,
                          }}
                        />
                      ) : null}
                      <span className="clio-cal__num">{d.day}</span>
                      {dot >= 0 ? (
                        <span
                          className="clio-cal__dot"
                          style={{ ["--clio-dot-delay" as string]: `${dot * 24}ms` }}
                        />
                      ) : null}
                    </span>
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </ClioTile>
  );
}
